@file:OptIn(ExperimentalJsExport::class)

package com.music.bitchord.web

import com.music.bitchord.data.model.SearchFilter
import com.music.bitchord.data.model.artworkAt as modelArtworkAt
import com.music.bitchord.data.model.playlistMoves as modelPlaylistMoves

/*
 * The web player's door into shared/commonMain: the same code the Android app runs,
 * compiled to JavaScript (web/shared-kotlin, regenerated by `./gradlew :shared:exportWeb`).
 *
 * Only this file is web-specific. It adapts Kotlin lists to JavaScript arrays and
 * nothing more: every rule lives in commonMain, so a change to one on Android is the
 * same change on the web at the next regeneration, which CI does by itself.
 */

/** Models.kt `String?.artworkAt`: [url] at the rendition that suits [px] (YouTube thumbnails upgraded). */
@JsExport
fun artworkAt(url: String?, px: Int): String? = url.modelArtworkAt(px)

/** PlaylistOrder.kt `PlaylistMove`: move [setVideoId] before [before] (null = to the end). */
@JsExport
class PlaylistMove(val setVideoId: String, val before: String?)

/** PlaylistOrder.kt `playlistMoves`: the fewest moves that turn [current] into [target]. */
@JsExport
fun playlistMoves(current: Array<String>, target: Array<String>): Array<PlaylistMove> =
    modelPlaylistMoves(current.toList(), target.toList()).map { PlaylistMove(it.setVideoId, it.before) }.toTypedArray()

/** Models.kt `SearchFilter`, the search chips: YouTube Music's params, and which need sign-in. */
@JsExport
class SearchFilterOption(val id: String, val label: String, val params: String?, val requiresAuth: Boolean)

@JsExport
fun searchFilters(): Array<SearchFilterOption> =
    SearchFilter.entries.map { SearchFilterOption(it.name, it.label, it.params, it.requiresAuth) }.toTypedArray()
